const toggleDropdown=document.getElementById("toggle-dropdown"),orderSummaryDropdown=document.getElementById("order-summary-dropdown");toggleDropdown.addEventListener("click",(()=>{orderSummaryDropdown.style.display="block"===orderSummaryDropdown.style.display?"none":"block"}));const renderCartFromLocalStorage=()=>{const e=document.getElementById("cart-items-container"),t=document.getElementById("combined-price"),n=JSON.parse(localStorage.getItem("cartItems"))||[];if(0===n.length)e.innerHTML="<p>Your cart is empty.</p>",t.textContent="0.00";else{e.innerHTML="";let d=0;n.forEach((t=>{const n=document.createElement("div");n.classList.add("cart-item");const o=(t.newPrice||"0").replace(/KSh|,/g,"").trim(),i=parseFloat(o)||0,a=parseInt(t.quantity)||1,s=i*a;d+=s,n.innerHTML=`\n        <div style="display: grid;">\n          \x3c!-- Product Image --\x3e\n          <img src="${t.image}" alt="${t.name}" style="width:70px; height:auto;">\n          \n          \x3c!-- Product Details --\x3e\n          <h4>${t.name}</h4>\n          <p>Brand: ${t.brand}</p>\n          <p>Price: KSh${i.toFixed(2)}</p>\n          <p>Qty: ${a}</p>\n          \n          \x3c!-- Display Size if available --\x3e\n          ${t.size?`<p>Size: ${t.size}</p>`:""}\n\n          \x3c!-- Display Color if available --\x3e\n          ${t.color?`\n            <p>Color: \n              <span style="background-color:${t.color}; padding:5px; border-radius:50%;">&nbsp;</span>\n            </p>`:""}\n\n          <p>Total Price: KSh${s.toFixed(2)}</p>\n        </div>\n      `,e.appendChild(n)}));const o=d;t.textContent=o.toFixed(2)}};window.onload=renderCartFromLocalStorage;const discountCodes={SAVE10:10,FREESHIP:0,BIGSALE:20};document.getElementById("apply-discount-btn").addEventListener("click",(function(){const e=document.getElementById("discount-code").value.trim(),t=discountCodes[e],n=document.getElementById("combined-price");if(void 0!==t){const e=parseFloat(n.textContent)||0,d=e-e*t/100;n.textContent=d.toFixed(2),alert(`Discount code applied! You saved ${t}%.`)}else alert("Invalid discount code. Please try again.")}));const paymentMethods=document.querySelectorAll(".payment-method");paymentMethods.forEach((e=>{e.addEventListener("click",(function(){paymentMethods.forEach((e=>e.classList.remove("selected"))),e.classList.add("selected")}))}));const sameAsShippingRadio=document.getElementById("same-as-shipping"),differentBillingRadio=document.getElementById("different-billing"),sameAddressContainer=document.getElementById("same-address-container"),differentAddressContainer=document.getElementById("different-address-container");function capitalizeFirstLetter(e){return e.charAt(0).toUpperCase()+e.slice(1)}function goBack(){history.back()}sameAsShippingRadio.addEventListener("change",(function(){this.checked&&(sameAddressContainer.style.display="block",differentAddressContainer.style.display="none")})),differentBillingRadio.addEventListener("change",(function(){this.checked&&(sameAddressContainer.style.display="none",differentAddressContainer.style.display="block")})),sameAsShippingRadio.checked&&(sameAddressContainer.style.display="block",differentAddressContainer.style.display="none");